// Entry point for AI assistants: where the course index and teaching rules of each language are.
import type { APIRoute } from 'astro';
import { LANGUAGES } from '../i18n/ui';
import { aiUrl } from '../lib/tutor';

export const GET: APIRoute = () => {
	const lines = [
		'# AI-Tutored Finance',
		'',
		'An economics and finance course generated by AI, meant to be taught by an AI tutor. Read the teaching rules first, then the course index of the learner\'s language.',
		'',
		...LANGUAGES.flatMap((l) => [`## ${l.label}`, `- Teaching rules: ${aiUrl(l.code, 'protocol.md')}`, `- Course index: ${aiUrl(l.code, 'index.md')}`, '']),
	];
	return new Response(lines.join('\n'), { headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
};
